SELECT order_id, customer, quantity, unit_price, discount_pct,
       line_total, total_gst
  FROM orders;

UPDATE orders SET quantity = 3 WHERE order_id = 1;

SELECT order_id, quantity, line_total, total_gst
  FROM orders
 WHERE order_id = 1;

INSERT INTO orders (customer, quantity, unit_price, line_total)
VALUES ('Kiran', 1, 100, DEFAULT)
RETURNING order_id, line_total, total_gst;

CREATE TABLE sales_virtual (
  id         bigint GENERATED ALWAYS AS IDENTITY,
  quantity   integer NOT NULL,
  unit_price numeric(10,2) NOT NULL,
  amount     numeric GENERATED ALWAYS AS (quantity * unit_price) VIRTUAL,
  summary    text GENERATED ALWAYS AS
               ('Qty ' || quantity::text || ' x Rs ' || unit_price::text) VIRTUAL
);

CREATE TABLE sales_stored (
  id         bigint GENERATED ALWAYS AS IDENTITY,
  quantity   integer NOT NULL,
  unit_price numeric(10,2) NOT NULL,
  amount     numeric GENERATED ALWAYS AS (quantity * unit_price) STORED,
  summary    text GENERATED ALWAYS AS
               ('Qty ' || quantity::text || ' x Rs ' || unit_price::text) STORED
);

INSERT INTO sales_virtual (quantity, unit_price)
SELECT 1 + g % 10, 100 + g % 900 FROM generate_series(1, 1000000) AS g;

INSERT INTO sales_stored (quantity, unit_price)
SELECT 1 + g % 10, 100 + g % 900 FROM generate_series(1, 1000000) AS g;

VACUUM ANALYZE sales_virtual;
VACUUM ANALYZE sales_stored;

SELECT relname, pg_size_pretty(pg_table_size(oid)) AS table_size
  FROM pg_class
 WHERE relname IN ('sales_virtual', 'sales_stored');

SELECT pg_relation_filenode('orders') AS filenode_before;

ALTER TABLE orders
  ADD COLUMN unit_price_usd numeric
  GENERATED ALWAYS AS (round(unit_price / 88, 2)) VIRTUAL;

SELECT pg_relation_filenode('orders') AS after_virtual;

ALTER TABLE orders
  ADD COLUMN big_order boolean
  GENERATED ALWAYS AS (quantity >= 5) STORED;

SELECT pg_relation_filenode('orders') AS after_stored;

CREATE INDEX sales_stored_amount_idx ON sales_stored (amount);

EXPLAIN (COSTS OFF)
SELECT count(*) FROM sales_stored WHERE amount > 9900;

CREATE INDEX sales_virtual_amount_expr_idx
    ON sales_virtual ((quantity * unit_price));

ANALYZE sales_virtual;

EXPLAIN (COSTS OFF)
SELECT count(*) FROM sales_virtual WHERE amount > 9900;

SELECT attname, n_distinct
  FROM pg_stats
 WHERE tablename = 'sales_stored' AND attname = 'amount';

SELECT attname, n_distinct
  FROM pg_stats
 WHERE tablename = 'sales_virtual' AND attname = 'amount';

CREATE TABLE customers (
  customer_id integer PRIMARY KEY,
  profile     jsonb NOT NULL,
  city        text GENERATED ALWAYS AS (profile ->> 'city') STORED
);

INSERT INTO customers VALUES
  (1, '{"name": "Asha", "city": "Pune", "tier": "gold"}'),
  (2, '{"name": "Ravi", "city": "Chennai"}'),
  (3, '{"name": "Meena"}');

CREATE INDEX customers_city_idx ON customers (city);

SELECT customer_id, profile ->> 'name' AS name, city
  FROM customers
 ORDER BY customer_id;

UPDATE customers
   SET profile = profile || '{"city": "Bengaluru"}'
 WHERE customer_id = 3;

SELECT customer_id, city FROM customers WHERE city = 'Bengaluru';

ALTER TABLE orders
  ALTER COLUMN total_gst
  SET EXPRESSION AS (round(quantity * unit_price * (1 - discount_pct / 100) * 1.12, 2));

ANALYZE orders;

SELECT order_id, line_total, total_gst FROM orders ORDER BY order_id;

CREATE TABLE invoices (
  invoice_id integer,
  issued_at  timestamptz,
  age        interval GENERATED ALWAYS AS (now() - issued_at)
);

CREATE TABLE staff (
  first_name text,
  last_name  text,
  full_name  text GENERATED ALWAYS AS (concat_ws(' ', first_name, last_name))
);

CREATE TABLE staff (
  first_name text NOT NULL,
  last_name  text NOT NULL,
  full_name  text GENERATED ALWAYS AS (first_name || ' ' || last_name)
);
INSERT INTO staff VALUES ('Priya', 'Sharma'), ('Arjun', 'Nair');
SELECT * FROM staff;

CREATE TABLE prices (
  net     numeric,
  gst     numeric GENERATED ALWAYS AS (net * 0.18),
  gross   numeric GENERATED ALWAYS AS (net + gst)
);

CREATE FUNCTION add_gst(amount numeric) RETURNS numeric
  LANGUAGE sql IMMUTABLE
  AS $$ SELECT round(amount * 1.18, 2) $$;

CREATE TABLE bills (
  net   numeric,
  gross numeric GENERATED ALWAYS AS (add_gst(net))
);

CREATE TABLE bills (
  net   numeric,
  gross numeric GENERATED ALWAYS AS (add_gst(net)) STORED
);
INSERT INTO bills (net) VALUES (100) RETURNING net, gross;

SET enable_seqscan = off;
CREATE INDEX orders_line_total_expr_idx
    ON orders ((quantity * unit_price * (1 - discount_pct / 100)));
EXPLAIN (COSTS OFF) SELECT order_id FROM orders WHERE line_total > 1000;

CREATE INDEX orders_line_total_cast_idx
    ON orders (((quantity * unit_price * (1 - discount_pct / 100))::numeric(12,2)));
EXPLAIN (COSTS OFF) SELECT order_id FROM orders WHERE line_total > 1000;
RESET enable_seqscan;

